package com.southstand.football.matchdata;
import static org.assertj.core.api.Assertions.assertThat;import java.nio.file.Files;import java.nio.file.Path;import org.junit.jupiter.api.Test;
class T17IncrementalIdempotencyTests{@Test void rosterAndMatchSeedsUseStableRangesAndExistenceGuards()throws Exception{String r=Files.readString(Path.of("scripts/sql/seed-t17-roster-expansion.sql")).toUpperCase();String m=Files.readString(Path.of("scripts/sql/seed-t17-incremental.sql")).toUpperCase();assertThat(r).contains("33000000000000001","WHERE NOT EXISTS","T17_DEMO_ROSTER").doesNotContain("DELETE FROM","TRUNCATE TABLE","DROP DATABASE");assertThat(m).contains("WHERE NOT EXISTS","LIMIT 20").doesNotContain("DELETE FROM","TRUNCATE TABLE","DROP DATABASE","UPDATE MATCH_INFO","UPDATE MATCH_EVENT");}}
